fn resolve_rules_for_element_with_context<'a>(
    element: GeckoElement<'a>,
    mut context: StyleContext<GeckoElement<'a>>,
    rules: StrongRuleNode,
    original_computed_values: &ComputedValues,
) -> Arc<ComputedValues> {
    use style::style_resolver::{PseudoElementResolution, StyleResolverForElement};

    // This currently ignores visited styles, which seems acceptable, as
    // existing browsers don't appear to animate visited styles.
    let inputs = CascadeInputs {
        rules: Some(rules),
        visited_rules: None,
        flags: original_computed_values.flags.for_cascade_inputs(),
        included_cascade_flags: RuleCascadeFlags::empty(),
    };

    // Actually `PseudoElementResolution` doesn't matter.
    let mut resolver = StyleResolverForElement::new(
        element,
        &mut context,
        RuleInclusion::All,
        PseudoElementResolution::IfApplicable,
    );
    resolver
        .cascade_style_and_visited_with_default_parents(inputs)
        .0
}

pub extern "C" fn Servo_StyleSet_GetBaseComputedValuesForElement(
    raw_style_set: &PerDocumentStyleData,
    element: &RawGeckoElement,
    computed_values: &ComputedValues,
    snapshots: *const ServoElementSnapshotTable,
) -> Strong<ComputedValues> {
    debug_assert!(!snapshots.is_null());
    let computed_values = unsafe { ArcBorrow::from_ref(computed_values) };

    let rules = match computed_values.rules {
        None => return computed_values.clone_arc().into(),
        Some(ref rules) => rules,
    };

    let doc_data = raw_style_set.borrow();
    let without_animations_rules = doc_data.stylist.rule_tree().remove_animation_rules(rules);
    if without_animations_rules == *rules {
        return computed_values.clone_arc().into();
    }

    let element = GeckoElement(element);

    let global_style_data = &*GLOBAL_STYLE_DATA;
    let guard = global_style_data.shared_lock.read();
    let shared = create_shared_context(
        &global_style_data,
        &guard,
        &doc_data.stylist,
        TraversalFlags::empty(),
        unsafe { &*snapshots },
    );
    let mut tlc = ThreadLocalStyleContext::new();
    tlc.current_dom_depth = element.as_node().depth();
    let context = StyleContext {
        shared: &shared,
        thread_local: &mut tlc,
    };

    resolve_rules_for_element_with_context(
        element,
        context,
        without_animations_rules,
        &computed_values,
    )
    .into()
}

/// Returns new rule node without rules from declarative animations.
pub fn remove_animation_rules(&self, path: &StrongRuleNode) -> StrongRuleNode {
    // Return a clone if there are no animation rules.
    if !path.has_animation_or_transition_rules() {
        return path.clone();
    }

    let iter = path.self_and_ancestors().take_while(|node| {
        node.cascade_level() >= CascadeLevel::new(CascadeOrigin::SMILOverride)
    });
    let mut last = path;
    let mut children = SmallVec::<[_; 10]>::new();
    for node in iter {
        if !node.cascade_level().is_animation() {
            children.push((
                node.style_source().unwrap().clone(),
                node.cascade_priority(),
            ));
        }
        last = node;
    }

    self.insert_ordered_rules_from(
        last.parent().unwrap().clone(),
        children.iter().rev().map(|(s, p)| (s.borrow(), *p)),
    )
}

fn init_custom_properties(&mut self, context: &mut computed::Context) {
    let is_root_element = context.is_root_element();
    let initial_values = self.stylist.get_custom_property_initial_values();
    let inherited = if is_root_element {
        debug_assert!(context.inherited_custom_properties().is_empty());
        initial_values.inherited.clone()
    } else {
        context.inherited_custom_properties().inherited.clone()
    };
    let properties = ComputedCustomProperties {
        inherited,
        non_inherited: initial_values.non_inherited.clone(),
    };
    context.builder.substitution_functions =
        ComputedSubstitutionFunctions::new(Some(properties), None);
}

