pub fn substitute<'a>(
    variable_value: &'a VariableValue,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
) -> Result<SubstitutionResult<'a>, ()> {
    debug_assert!(variable_value.has_references());
    let mut attr_taint = AttrTaint::default();
    let v = substitute_internal(
        variable_value,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        attribute_tracker,
        &mut SubstitutionState::default(),
        Some(&mut attr_taint),
    )?;
    Ok(SubstitutionResult {
        css: v.css,
        attr_taint,
    })
}

void nsAnimationManager::DoUpdateAnimations(
    const NonOwningAnimationTarget& aTarget, const nsStyleUIReset& aStyle,
    ServoCSSAnimationBuilder& aBuilder, const nsStyleUIReset* aDurationInput,
    bool aVerifyDurationInputOnly) {
  // Everything that causes our animation data to change triggers a
  // style change, which in turn triggers a non-animation restyle.
  // Likewise, when we initially construct frames, we're not in a
  // style change, but also not in an animation restyle.

  auto* collection =
      CSSAnimationCollection::Get(aTarget.mElement, aTarget.mPseudoRequest);
  if (!collection && aStyle.mAnimationNameCount == 1 &&
      aStyle.mAnimations[0].GetName() == nsGkAtoms::_empty) {
    return;
  }

  if (aVerifyDurationInputOnly && !collection) {
    return;
  }

  nsTArray<StyleAnimationDuration> durationInput;
  if (aDurationInput) {
    durationInput.SetCapacity(aDurationInput->mAnimationDurationCount);
    for (uint32_t i = 0; i < aDurationInput->mAnimationDurationCount; ++i) {
      durationInput.AppendElement(aDurationInput->GetAnimationDuration(i));
    }
    if (aVerifyDurationInputOnly &&
        collection->mLastAnimationDurationInput == durationInput) {
      return;
    }
  }

  nsAutoAnimationMutationBatch mb(aTarget.mElement->OwnerDoc());

  // Build the updated animations list. Even if we remove entries in
  // `mAnimationsWithNamedTimeline` in this function later, entries are added
  // when we build the list, breaking the symmetry. This is unfortunate, but
  // unavoidable, because `newAmimations.Length()` does not necessarily equal to
  // the length of animations defined in `aStyle`, e.g. when a referenced
  // `animiation-name` does not exist.
  //
  // Old entries in `collection` may be reused. If they are, they are removed
  // from `collection` and put into `newAnimations`.
  OwningCSSAnimationPtrArray newAnimations =
      BuildAnimations(mPresContext, aTarget, aStyle, durationInput, aBuilder,
                      collection, mMaybeReferencedAnimations,
                      mAnimationsWithNamedTimeline);
